/** Search local/remote: case-insensitive + no-diacritics + collapse spaces — parity Master `codeField.normalizeSearchText`. */
export const normalizeSearchText = (value?: string): string => {
  if (!value) return '';
  return value
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
};
